/**
 * Required-documents checklist builder (T044, FR-015). Maps extracted requirements to vault document
 * types or to generated annexures (rendered by the Apply module's templates). Item ids are stable so
 * the workspace's checklist→vault mapping survives a re-analysis.
 */
import type { ChecklistItem, DocType, Requirement } from './types';
import { inr } from './format';
import { certMatches, isValidDoc, type ScoreVaultDoc } from './vault-match';
import { EXPIRING_WITHIN_DAYS, daysUntilExpiry } from '../vault/status';

/** Annexure template keys generated by the Apply module (packages/core/src/packet). */
export const ANNEXURE_KEYS = {
  nonBlacklisting: 'non_blacklisting',
  miiSelfCert: 'mii_self_cert',
  mseDeclaration: 'mse_declaration',
  emdExemption: 'emd_exemption',
  oemAuthRequest: 'oem_auth_request',
  technicalCompliance: 'technical_compliance',
  authorityLetter: 'authority_letter',
} as const;

export interface ChecklistProfile {
  mseCategory?: 'micro' | 'small' | 'medium' | null;
  udyamNumber?: string | null;
  isStartup?: boolean | null;
  dpiitNumber?: string | null;
}

export const isMseProfile = (p: ChecklistProfile | null | undefined) => !!p && (!!p.mseCategory || !!p.udyamNumber);
export const isStartupProfile = (p: ChecklistProfile | null | undefined) => !!p && (!!p.isStartup || !!p.dpiitNumber);

const slug = (s: string) => s.toLowerCase().replace(/\([^)]*\)/g, ' ').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 40) || 'item';

const quoteOf = (r?: Requirement) => (r?.source.page ? ` (bid document, page ${r.source.page})` : '');

export function buildChecklist(requirements: Requirement[], profile: ChecklistProfile | null): ChecklistItem[] {
  const items = new Map<string, ChecklistItem>();
  const add = (it: ChecklistItem) => { if (!items.has(it.id)) items.set(it.id, it); };
  const get = (k: string) => requirements.find((r) => r.key === k);
  const all = (k: string) => requirements.filter((r) => r.key === k);
  const yes = (k: string) => get(k)?.value === true;

  // Identity — always needed on GeM.
  add({ id: 'gst', label: 'GST registration certificate', docType: 'gst', mandatory: true, reason: 'Seller identity and tax registration (standard GeM requirement)' });
  add({ id: 'pan', label: 'PAN card of the firm', docType: 'pan', mandatory: true, reason: 'Seller identity (standard GeM requirement)' });

  const turnover = get('turnover_min');
  const experience = get('experience_years');
  const docs = all('document');
  const docText = docs.map((d) => String(d.value ?? d.label)).join(' | ');
  const mse = isMseProfile(profile);
  const startup = isStartupProfile(profile);

  const turnoverItems = (reason: string) => {
    add({ id: 'balance_sheets', label: 'Audited balance sheets — last 3 financial years', docType: 'balance_sheet', mandatory: true, reason });
    add({ id: 'ca_turnover_certificate', label: 'CA certificate of average annual turnover', docType: 'ca_turnover_certificate', mandatory: true, reason });
  };
  const experienceItems = (reason: string) => {
    add({ id: 'experience_proof', label: 'Work orders with completion certificates (CRAC) as proof of experience', docType: 'crac', mandatory: true, reason });
  };

  if (turnover) turnoverItems(`Minimum average turnover of ${inr(turnover.numeric ?? null)} required${quoteOf(turnover)}`);
  if (experience) experienceItems(`${experience.numeric ?? '?'} year(s) of past experience required${quoteOf(experience)}`);

  for (const d of docs) {
    const t = String(d.value ?? d.label);
    const reason = `Listed under "Document required from seller": ${t}`;
    if (/oem.*turnover/i.test(t)) add({ id: 'oem_turnover_certificate', label: "OEM's turnover certificate (from the OEM's CA)", docType: 'other', mandatory: true, reason });
    else if (/turnover/i.test(t)) turnoverItems(reason);
    else if (/experience/i.test(t)) experienceItems(reason);
    else if (/past performance/i.test(t)) add({ id: 'past_performance_proof', label: 'Past performance proof (supply orders for similar quantity)', docType: 'work_order', mandatory: true, reason });
    else if (/oem authori[sz]ation/i.test(t)) add({ id: 'oem_authorization', label: 'OEM authorisation certificate (MAF) for this bid', docType: 'oem_authorization', mandatory: true, reason });
    else if (/boq|specification|technical compliance/i.test(t)) add({ id: 'technical_compliance', label: 'Technical compliance sheet (BOQ specification)', docType: null, mandatory: true, reason, generated: ANNEXURE_KEYS.technicalCompliance });
    else if (/certificate\s*\(requested in atc\)/i.test(t)) { /* expanded from certificate requirements below */ }
    else if (/additional doc/i.test(t)) add({ id: `atc_${slug(t)}`, label: `${t.replace(/\s*\(Requested in ATC\)/i, '')} — as specified in the ATC`, docType: 'other', mandatory: true, reason: `${reason}. Check the ATC clauses for what to upload.` });
    else add({ id: `doc_${slug(t)}`, label: t, docType: 'other', mandatory: d.mandatory, reason });
  }

  if (get('past_performance')) {
    add({ id: 'past_performance_proof', label: 'Past performance proof (supply orders for similar quantity)', docType: 'work_order', mandatory: true, reason: `Past performance of ${get('past_performance')?.numeric ?? '?'}% of bid quantity required${quoteOf(get('past_performance'))}` });
  }

  // Similar work → CRAC/work order of that value
  const similar = get('similar_work');
  if (similar) {
    add({ id: 'similar_work_proof', label: `Work order + CRAC for one similar work${similar.numeric ? ` of at least ${inr(similar.numeric)}` : ''}`, docType: 'crac', mandatory: true, reason: `Similar-work condition${quoteOf(similar)}` });
  }

  // Certificates from ATC
  const certs = all('certificate');
  for (const c of certs) {
    const name = String(c.value ?? c.label);
    const docType: DocType = /^ISO/i.test(name) ? 'iso' : /^BIS/i.test(name) ? 'bis' : 'other';
    add({ id: `cert_${slug(name)}`, label: `${name} certificate`, docType, mandatory: c.mandatory, reason: `Requested in the ATC${quoteOf(c)}` });
  }
  if (!certs.length && /certificate\s*\(requested in atc\)/i.test(docText)) {
    add({ id: 'atc_certificates', label: 'Certificates requested in the ATC', docType: 'other', mandatory: true, reason: 'Listed as "Certificate (Requested in ATC)" — check the ATC clauses' });
  }

  // OEM authorisation (from ATC or document list)
  const oem = get('oem_auth');
  if (oem && oem.value !== false) {
    add({ id: 'oem_authorization', label: 'OEM authorisation certificate (MAF) for this bid', docType: 'oem_authorization', mandatory: true, reason: `OEM authorisation required${quoteOf(oem)}` });
  }

  // EMD & exemptions
  const emd = get('emd');
  const emdAmount = emd?.numeric ?? 0;
  const mseExemptTurnoverExp = yes('mse_exemption');
  const startupExemptTurnoverExp = yes('startup_exemption');
  if (emdAmount > 0) {
    if (mse) {
      add({ id: 'udyam', label: 'Udyam registration certificate (MSE)', docType: 'udyam', mandatory: true, reason: `Claim EMD exemption of ${inr(emdAmount)} as a registered MSE` });
      add({ id: 'emd_exemption', label: 'EMD exemption declaration', docType: null, mandatory: true, reason: `EMD of ${inr(emdAmount)} is exempt for MSEs with a valid Udyam certificate`, generated: ANNEXURE_KEYS.emdExemption });
    } else if (startup) {
      add({ id: 'startup_dpiit', label: 'DPIIT Startup recognition certificate', docType: 'startup_dpiit', mandatory: true, reason: `Claim EMD exemption of ${inr(emdAmount)} as a DPIIT-recognised Startup` });
      add({ id: 'emd_exemption', label: 'EMD exemption declaration', docType: null, mandatory: true, reason: `EMD of ${inr(emdAmount)} is exempt for DPIIT-recognised Startups`, generated: ANNEXURE_KEYS.emdExemption });
    } else {
      add({ id: 'emd_payment', label: `EMD of ${inr(emdAmount)} — pay online or submit bank guarantee on GeM`, docType: null, mandatory: false, reason: 'EMD is paid by you on GeM; keep the payment / BG reference handy' });
    }
  }
  if (mseExemptTurnoverExp && mse && (turnover || experience)) {
    add({ id: 'udyam', label: 'Udyam registration certificate (MSE)', docType: 'udyam', mandatory: true, reason: 'Claim the MSE exemption from experience and turnover criteria' });
    add({ id: 'mse_declaration', label: 'MSE exemption declaration', docType: null, mandatory: true, reason: 'Supporting declaration for the MSE exemption claim', generated: ANNEXURE_KEYS.mseDeclaration });
  }
  if (startupExemptTurnoverExp && startup && (turnover || experience)) {
    add({ id: 'startup_dpiit', label: 'DPIIT Startup recognition certificate', docType: 'startup_dpiit', mandatory: true, reason: 'Claim the Startup exemption from experience and turnover criteria' });
  }
  if (yes('mse_purchase_preference') && mse) {
    add({ id: 'udyam', label: 'Udyam registration certificate (MSE)', docType: 'udyam', mandatory: false, reason: 'Avail MSE purchase preference' });
  }

  // Make in India
  const mii = get('mii');
  if (mii?.value === true) {
    add({ id: 'mii_self_cert', label: 'Make in India self-certificate (local content %)', docType: null, mandatory: true, reason: `MII compliance required${quoteOf(mii)}`, generated: ANNEXURE_KEYS.miiSelfCert });
  }

  // Undertakings
  const nb = requirements.find((r) => r.key === 'undertaking' && r.value === 'non_blacklisting');
  add({
    id: 'non_blacklisting', label: 'Non-blacklisting / non-debarment undertaking', docType: null, mandatory: !!nb,
    reason: nb ? `Requested in the ATC${quoteOf(nb)}` : 'Recommended with every GeM bid', generated: ANNEXURE_KEYS.nonBlacklisting,
  });
  for (const u of requirements.filter((r) => r.key === 'undertaking' && r.value !== 'non_blacklisting')) {
    const name = String(u.label);
    add({ id: `undertaking_${slug(name)}`, label: name, docType: 'other', mandatory: u.mandatory, reason: `Requested in the bid${quoteOf(u)}` });
  }
  // LLM "other" requirements that are documents
  for (const o of requirements.filter((r) => r.key === 'other' && r.method === 'LLM' && /certificate|registration|licen[cs]e|undertaking|declaration|copy of/i.test(r.label))) {
    add({ id: `doc_${slug(o.label)}`, label: o.label, docType: 'other', mandatory: o.mandatory, reason: `Found by AI in the bid${quoteOf(o)}` });
  }

  return [...items.values()];
}

export type ChecklistReadiness =
  | { status: 'ready' }
  | { status: 'expiring'; days: number }
  | { status: 'expired' }
  | { status: 'missing' }
  | { status: 'n/a' };

/**
 * Per-item vault readiness for the tender-page checklist (FR-040). Shares the scoring rules: validity is
 * `isValidDoc` (expiry date ≥ now, end of day 23:59:59 IST) and `cert_*` items use the Certificates-factor
 * matcher (title/tags, so ISO 9001 is not ISO 27001). Items without a vault type (generated annexures,
 * "Action on GeM") and items typed `other` (ATC/free-text documents, unrecognised certificates) are `n/a`.
 * With several matching documents the one expiring last decides.
 */
export function checklistReadiness(items: ChecklistItem[], vaultDocs: ScoreVaultDoc[], now: Date): Record<string, ChecklistReadiness> {
  const out: Record<string, ChecklistReadiness> = {};
  for (const item of items) {
    if (!item.docType || item.docType === 'other' || item.generated) { out[item.id] = { status: 'n/a' }; continue; }
    const certName = item.id.startsWith('cert_') ? item.label.replace(/\s+certificate$/i, '') : null;
    const docs = vaultDocs.filter((d) => (certName != null ? certMatches(certName, d) : d.type === item.docType));
    if (!docs.length) { out[item.id] = { status: 'missing' }; continue; }
    const valid = docs.filter((d) => isValidDoc(d, now));
    if (!valid.length) { out[item.id] = { status: 'expired' }; continue; }
    let best = Infinity;
    for (const d of valid) {
      const days = daysUntilExpiry(d.expiryDate, now);
      if (days == null) { best = Infinity; break; }
      best = best === Infinity ? days : Math.max(best, days);
    }
    out[item.id] = best > EXPIRING_WITHIN_DAYS ? { status: 'ready' } : { status: 'expiring', days: best };
  }
  return out;
}
